type TemplateHandler = (event: any, element: any, features: FeatureRegistry) => any;
const dom = document as any;

function setKnowledgePanel(open?: boolean): void {
  const panel = document.getElementById('kbPanel');
  const button = document.getElementById('navKBBtn');
  if (!panel || !button) return;
  const shouldOpen = typeof open === 'boolean' ? open : !panel.classList.contains('open');
  panel.classList.toggle('open', shouldOpen);
  panel.toggleAttribute('inert', !shouldOpen);
  panel.setAttribute('aria-hidden', shouldOpen ? 'false' : 'true');
  button.classList.toggle('active', shouldOpen);
  button.setAttribute('aria-expanded', shouldOpen ? 'true' : 'false');
  if (shouldOpen) void Promise.resolve(getFeatureRegistry().loadWorkspaceBundle?.())
    .then(() => getFeatureRegistry().loadKnowledgePanel?.()).catch(() => {});
}

