function dispatchTemplateEvent(event: Event): void {
  const target = event.target instanceof Element ? event.target : null;
  const element = target?.closest<HTMLElement>(`[data-koto-event-${event.type}]`);
  if (!element) return;
  const handlerId = element.getAttribute(`data-koto-event-${event.type}`) || '';
  const handler = handlers[handlerId];
  if (!handler) return;
  const result = handler(event, element, getFeatureRegistry());
  if (result === false) { event.preventDefault(); event.stopPropagation(); }
}

const templateEventTypes = ["blur", "change", "click", "dragover", "dragleave", "drop", "input", "keydown", "mousedown"] as const;
templateEventTypes.forEach((eventType) => document.addEventListener(eventType, dispatchTemplateEvent, true));

export const templateEventHandlerCount = Object.keys(handlers).length;
